/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var isObject = require( '@stdlib/assert/is-object' );
var isScaleNameArray = require( '@stdlib/plot/vega/base/assert/is-scale-name-array' );
var hasProp = require( '@stdlib/assert/has-property' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var setNonEnumerableProperty = require( '@stdlib/utils/define-nonenumerable-property' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var contains = require( '@stdlib/array/base/assert/contains' );
var join = require( '@stdlib/array/base/join' );
var dedupe = require( '@stdlib/array/base/dedupe' );
var objectAssignIn = require( '@stdlib/object/assign-in' );
var inherit = require( '@stdlib/utils/inherit' );
var ctors = require( '@stdlib/plot/vega/scale/ctors' );
var Scale = require( '@stdlib/plot/vega/scale/base/ctor' );
var format = require( '@stdlib/string/format' );
var changeEvent = require( './change_event.js' );
var properties = require( './properties.json' );


// VARIABLES //

var debug = logger( 'vega:generalized-scale:main' );
var DEFAULT_NAME = 'scale';


// MAIN //

/**
* Returns a generalized scale constructor.
*
* @param {Array<string>} scales - list of supported scale names
* @param {Options} [defaults] - defaults
* @param {string} [defaults.name='scale'] - default scale name
* @param {string} [defaults.type=scales[0]] - default scale type
* @throws {TypeError} first argument must be an array of scale names
* @throws {TypeError} second argument must be an object
* @throws {TypeError} must provide valid options
* @returns {Function} constructor
*
* @example
* var scales = [ 'linear', 'log' ];
*
* var GeneralizedScale = factory( scales, {
*     'name': 'xScale'
* });
* // returns <Function>
*
* var xScale = GeneralizedScale();
* // returns <GeneralizedScale>
*/
function factory( scales, defaults ) {
	var cache;
	var props;
	var OPTS;
	var tmp;
	var k;
	var i;
	if ( !isScaleNameArray( scales ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be an array of scale names. Value: `%s`.', scales ) );
	}
	OPTS = {
		'name': DEFAULT_NAME,
		'type': scales[ 0 ]
	};
	if ( arguments.length > 1 ) {
		if ( !isPlainObject( defaults ) ) {
			throw new TypeError( format( 'invalid argument. Second argument must be an object. Value: `%s`.', defaults ) );
		}
		if ( hasOwnProp( defaults, 'name' ) ) {
			if ( !isString( defaults.name ) ) {
				throw new TypeError( format( 'invalid option. `%s` option must be a string. Option: `%s`.', 'name', defaults.name ) );
			}
			OPTS.name = defaults.name;
		}
		if ( hasOwnProp( defaults, 'type' ) ) {
			if ( !contains( scales, defaults.type ) ) {
				throw new TypeError( format( 'invalid option. `%s` option must be one of the following: "%s". Option: `%s`.', 'type', join( scales, '", "' ), defaults.type ) );
			}
			OPTS.type = defaults.type;
		}
	}
	// Initialize a cache for storing scale instances:
	cache = {};

	// Resolve the list of property names which are unique to the list of provided scales...
	props = properties.all.slice();
	for ( i = 0; i < scales.length; i++ ) {
		tmp = properties[ scales[ i ] ];
		for ( k = 0; k < tmp.length; k++ ) {
			props.push( tmp[ k ] );
		}
	}
	props = dedupe( props.sort() );

	/**
	* Returns the scale type.
	*
	* @private
	* @returns {string} scale type
	*/
	function getType() {
		return this.__scale__.type;
	}

	/**
	* Sets the scale type.
	*
	* @private
	* @param {string} value - input value
	* @throws {TypeError} must be a valid scale
	* @returns {void}
	*/
	function setType( value ) {
		var scale;
		var ctor;
		var curr;
		var k;
		var v;
		var i;

		curr = this.type;
		if ( value === curr ) {
			return;
		}
		if ( !contains( scales, value ) ) {
			throw new TypeError( format( 'invalid assignment. `%s` must be one of the following: "%s". Value: `%s`.', 'type', join( scales, '", "' ), value ) );
		}
		debug( 'Current value: %s. New value: %s.', curr, value );
		if ( hasOwnProp( cache, value ) ) {
			this.__scale__.removeListener( this._onChange );
			scale = cache[ value ];
		} else {
			ctor = ctors( value );
			scale = new ctor({
				'name': this.name
			});
		}
		// Attempt to set scale properties based on the current scale's configuration (imagined use case: a user toggles a scale type between 'linear' and 'log' and would like to see the domain min and max remain the same after toggling rather than the scale reverting to a previous state), while recognizing that some assignments may fail if transitioning between scales with incompatible fields (e.g., quantitative to discrete). In those cases, we simply skip assignment...
		for ( i = 0; i < props.length; i++ ) {
			k = props[ i ];
			if ( k === 'type' ) {
				continue;
			}
			v = this.__scale__[ k ];
			if ( v === void 0 ) {
				continue;
			}
			try {
				scale[ k ] = v;
			} catch ( err ) {
				debug( 'Encountered an error when attempting to assign the current scale property value to the new scale. Property: %s. Value: %s. Error: %s', k, JSON.stringify( v ), err.message );
				continue;
			}
		}
		this.__scale__ = scale;
		scale.on( 'change', this._onChange );
		this.emit( 'change', changeEvent( 'type' ) );
	}

	/**
	* Returns an accessor for retrieving a property value.
	*
	* @private
	* @param {string} name - property name
	* @returns {Function} accessor
	*/
	function getter( name ) {
		return get;

		/**
		* Returns a property value.
		*
		* @private
		* @returns {(*|void)} property value
		*/
		function get() {
			if ( hasProp( this.__scale__, name ) ) {
				// Forward the request to the underlying specialized scale:
				return this.__scale__[ name ];
			}
		}
	}

	/**
	* Returns an accessor for setting a property value.
	*
	* @private
	* @param {string} name - property name
	* @returns {Function} accessor
	*/
	function setter( name ) {
		return set;

		/**
		* Sets a property value.
		*
		* @private
		* @param {*} value - value to set
		*/
		function set( value ) {
			if ( hasProp( this.__scale__, name ) ) {
				// Forward the request to the underlying specialized scale:
				this.__scale__[ name ] = value;
			}
		}
	}

	/**
	* Generalized scale constructor.
	*
	* @private
	* @constructor
	* @param {Options} [options] - constructor options
	* @throws {TypeError} options argument must be an object
	* @throws {TypeError} must provide valid options
	* @returns {GeneralizedScale} scale instance
	*/
	function GeneralizedScale( options ) {
		var scale;
		var nargs;
		var opts;
		var ctor;
		var self;

		nargs = arguments.length;
		if ( !( this instanceof GeneralizedScale ) ) {
			if ( nargs ) {
				return new GeneralizedScale( options );
			}
			return new GeneralizedScale();
		}
		self = this;

		// Resolve constructor options...
		if ( nargs ) {
			if ( !isObject( options ) ) {
				throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
			}
			opts = objectAssignIn( {}, options );
			if ( !hasProp( opts, 'name' ) ) {
				opts.name = OPTS.name;
			}
		} else {
			opts = {
				'name': OPTS.name
			};
		}
		if ( hasProp( opts, 'type' ) ) {
			if ( !contains( scales, opts.type ) ) {
				throw new TypeError( format( 'invalid option. `%s` option must be one of the following: "%s". Option: `%s`.', 'type', join( scales, '", "' ), opts.type ) );
			}
		} else {
			opts.type = OPTS.type;
		}
		// Resolve a specialized scale constructor:
		ctor = ctors( opts.type );

		// Initialize a specialized scale type:
		scale = ctor( opts );

		// Add the scale to the cache:
		cache[ opts.type ] = scale;
		setNonEnumerableProperty( this, '__scale__', scale );

		// Set a callback for handling 'change' events from specialized constructors:
		setNonEnumerableReadOnly( this, '_onChange', onChange );

		// Setup event listeners:
		scale.on( 'change', this._onChange );

		// Call the parent constructor which ensures that the returned scale satisfies `instanceof Scale`:
		Scale.call( this, OPTS );

		return this;

		/**
		* Callback invoked upon receiving a change event.
		*
		* @private
		* @param {Object} event - event object
		*/
		function onChange( event ) {
			debug( 'Received a change event: %s', JSON.stringify( event ) );
			self.emit( 'change', event );
		}
	}

	/*
	* Inherit from the `Scale` prototype.
	*/
	inherit( GeneralizedScale, Scale );

	/**
	* Scale type.
	*
	* @name type
	* @memberof GeneralizedScale.prototype
	* @type {string}
	*/
	setReadWriteAccessor( GeneralizedScale.prototype, 'type', getType, setType );

	// Add prototype methods which forward requests to the underlying specialized scale instance...
	for ( i = 0; i < props.length; i++ ) {
		k = props[ i ];

		// Skip the 'type' property, as we use a specialized handler for switching between specialized scale types...
		if ( k === 'type' ) {
			continue;
		}
		// For other properties, we can delegate to the underlying specialized scale:
		setReadWriteAccessor( GeneralizedScale.prototype, k, getter( k ), setter( k ) ); // eslint-disable-line max-len
	}

	/**
	* Serializes an instance to a JSON object.
	*
	* ## Notes
	*
	* -   This method is implicitly invoked by `JSON.stringify`.
	*
	* @name toJSON
	* @memberof GeneralizedScale.prototype
	* @type {Function}
	* @returns {Object} JSON object
	*/
	setNonEnumerableReadOnly( GeneralizedScale.prototype, 'toJSON', function toJSON() {
		return this.__scale__.toJSON();
	});

	return GeneralizedScale;
}


// EXPORTS //

module.exports = factory;
